1	// Package contextcmd interprets the arguments of the :ctx command. It is pure:
2	// no I/O and no UI imports, so every decision is table-testable.
3	package contextcmd
4	
5	import (
6		"fmt"
7		"strings"
8	)
9	
10	// Snapshot is the state of the world Resolve decides against.
11	type Snapshot struct {
12		Names             []string
13		Current, Previous string
14		Ready             bool
15	}
16	
17	// Kind is what the caller must do with an Action.
18	type Kind int
19	
20	const (
21		// List opens the context list overlay.
22		List Kind = iota
23		// Switch loads the context named Name.
24		Switch
25		// Create creates the context named Name and switches to it.
26		Create
27		// Refuse does nothing but report Text.
28		Refuse
29		// KeepOpen leaves the command line open and reports Text.
30		KeepOpen
31	)
32	
33	// Level is the footer severity of an Action's Text.
34	type Level int
35	
36	const (
37		// Info is a neutral fact.
38		Info Level = iota
39		// Warn means the request cannot be honored as typed.
40		Warn
41		// Error means the request is invalid or failed.
42		Error
43	)
44	
45	// Action is the outcome of Resolve.
46	type Action struct {
47		Kind  Kind
48		Name  string
49		Level Level
50		Text  string
51	}
52	
53	const (
54		wordNew  = "new"
55		wordList = "list"
56		wordPrev = "-"
57	
58		textUsageNew = "Usage: :ctx new <name>"
59		textUsage    = "Usage: :ctx <name>"
60		textNoPrev   = "No previous context in this session"
61		textNotReady = "Contexts are still loading — try again"
62	)
63	
64	func textAlready(name string) string { return fmt.Sprintf("Already on context %q", name) }
65	
66	func textInvalid(name string) string {
67		return fmt.Sprintf("Invalid context name %q — use lowercase letters, digits and hyphens", name)
68	}
69	
70	func textReserved(name string) string {
71		return fmt.Sprintf("%q is reserved — choose another name", name)
72	}
73	
74	func textExists(name string) string {
75		return fmt.Sprintf("Context %q already exists — use :ctx %s to switch", name, name)
76	}
77	
78	func textAmbiguous(prefix string, matches []string) string {
79		return fmt.Sprintf("%q matches %s — type more letters or press tab", prefix, strings.Join(matches, ", "))
80	}
81	
82	func textNotFound(name string, names []string) string {
83		if near, ok := DidYouMean(name, names); ok {
84			return fmt.Sprintf("Context %q not found — did you mean %q? Use :ctx new %s to create it", name, near, name)
85		}
86		return fmt.Sprintf("Context %q not found — use :ctx new %s to create it", name, name)
87	}
88	
89	func refuse(level Level, text string) Action { return Action{Kind: Refuse, Level: level, Text: text} }
90	
91	func keepOpen(level Level, text string) Action {
92		return Action{Kind: KeepOpen, Level: level, Text: text}
93	}
94	
95	// validName reports whether name is made of lowercase letters, digits and
96	// hyphens only, mirroring config.ValidateContextName without importing it.
97	func validName(name string) bool {
98		if name == "" {
99			return false
100		}
101		for _, r := range name {
102			if (r < 'a' || r > 'z') && (r < '0' || r > '9') && r != '-' {
103				return false
104			}
105		}
106		return true
107	}
108	
109	func contains(names []string, name string) bool {
110		for _, n := range names {
111			if n == name {
112				return true
113			}
114		}
115		return false
116	}
117	
118	// switchTo switches to name, or reports that it is already the current one.
119	func switchTo(name string, s Snapshot) Action {
120		if name == s.Current {
121			return refuse(Info, textAlready(name))
122		}
123		return Action{Kind: Switch, Name: name}
124	}
125	
126	// Resolve interprets the words after :ctx. highlighted is the suggestion the
127	// user chose with tab, or "" when none was chosen.
128	func Resolve(args []string, highlighted string, s Snapshot) Action {
129		if len(args) == 0 || (len(args) == 1 && args[0] == wordList) {
130			return Action{Kind: List}
131		}
132		if !s.Ready {
133			return keepOpen(Warn, textNotReady)
134		}
135		if args[0] == wordNew {
136			return resolveNew(args[1:], s)
137		}
138		if len(args) > 1 {
139			return keepOpen(Warn, textUsage)
140		}
141		return resolveName(args[0], highlighted, s)
142	}
143	
144	// resolveNew handles ":ctx new <name>".
145	func resolveNew(rest []string, s Snapshot) Action {
146		if len(rest) != 1 {
147			return keepOpen(Warn, textUsageNew)
148		}
149		name := rest[0]
150		switch {
151		case name == wordNew || name == wordList || name == wordPrev:
152			return refuse(Error, textReserved(name))
153		case !validName(name):
154			return refuse(Error, textInvalid(name))
155		case contains(s.Names, name):
156			return refuse(Warn, textExists(name))
157		}
158		return Action{Kind: Create, Name: name}
159	}
160	
161	// resolveName handles ":ctx <arg>": previous, exact, prefix, or unknown.
162	func resolveName(arg, highlighted string, s Snapshot) Action {
163		if arg == wordPrev {
164			if s.Previous == "" {
165				return refuse(Warn, textNoPrev)
166			}
167			return Action{Kind: Switch, Name: s.Previous}
168		}
169		if !validName(arg) {
170			return refuse(Error, textInvalid(arg))
171		}
172		if contains(s.Names, arg) {
173			return switchTo(arg, s)
174		}
175		matches := Match(arg, s.Names)
176		switch {
177		case len(matches) == 0:
178			return refuse(Error, textNotFound(arg, s.Names))
179		case len(matches) == 1:
180			return switchTo(matches[0], s)
181		case contains(matches, highlighted):
182			return switchTo(highlighted, s)
183		}
184		return keepOpen(Warn, textAmbiguous(arg, matches))
185	}
186	
187	// Match returns the names starting with prefix (case-insensitive), an exact
188	// match first, the others in their original order.
189	func Match(prefix string, names []string) []string {
190		p := strings.ToLower(prefix)
191		out := []string{}
192		for _, n := range names {
193			if strings.ToLower(n) == p {
194				out = append(out, n)
195			}
196		}
197		for _, n := range names {
198			l := strings.ToLower(n)
199			if l != p && strings.HasPrefix(l, p) {
200				out = append(out, n)
201			}
202		}
203		return out
204	}
205	
206	// DidYouMean returns the closest name: edit distance <= 2, or one string a
207	// prefix of the other with the shorter one at least 3 characters long.
208	func DidYouMean(name string, names []string) (string, bool) {
209		best, bestDist := "", 3
210		for _, n := range names {
211			d := editDistance(name, n)
212			if d > 2 && !prefixRelated(name, n) {
213				continue
214			}
215			if d < bestDist || best == "" {
216				best, bestDist = n, min(d, bestDist)
217			}
218		}
219		return best, best != ""
220	}
221	
222	func prefixRelated(a, b string) bool {
223		short, long := a, b
224		if len(short) > len(long) {
225			short, long = long, short
226		}
227		return len(short) >= 3 && strings.HasPrefix(long, short)
228	}
229	
230	// editDistance is the Levenshtein distance between a and b.
231	func editDistance(a, b string) int {
232		ra, rb := []rune(a), []rune(b)
233		prev := make([]int, len(rb)+1)
234		for j := range prev {
235			prev[j] = j
236		}
237		for i := 1; i <= len(ra); i++ {
238			cur := make([]int, len(rb)+1)
239			cur[0] = i
240			for j := 1; j <= len(rb); j++ {
241				cost := 1
242				if ra[i-1] == rb[j-1] {
243					cost = 0
244				}
245				cur[j] = min(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
246			}
247			prev = cur
248		}
249		return prev[len(rb)]
250	}
251

