107	// normalize strips the leading colon and the case, so `:Status ` and `status`
108	// are the same command.
109	func normalize(input string) string {
110		return strings.ToLower(strings.TrimPrefix(strings.TrimSpace(input), ":"))
111	}
112	
113	// ParseCommand parses a command and returns a structured Command
114	func ParseCommand(input string) Command {
115		// Only the command word is case-insensitive; arguments (a context name,
116		// for instance) keep the case the user typed.
117		parts := strings.Fields(strings.TrimPrefix(strings.TrimSpace(input), ":"))
118		if len(parts) == 0 {
119			return Command{Type: CommandUnknown}
120		}
121	
122		mainCmd, args := strings.ToLower(parts[0]), parts[1:]
123		if full, isAlias := actionAliases[mainCmd]; isAlias {
124			mainCmd = full
125		}
126	
127		if action, ok := actionNames[mainCmd]; ok {
128			if action == CommandQuit {
129				return Command{Type: CommandQuit}
130			}
131			return Command{Type: action, Args: args}
132		}
133	
134		if view, ok := resolveView(mainCmd); ok {
135			return Command{Type: CommandView, View: view}
136		}
137	
138		return Command{Type: CommandUnknown}
139	}
