141	// Parse resolves a view name alone, without action commands. This is the form
142	// used to read `default_view` in configuration.
143	// Returns an empty view, without error, when the name is not recognized.
144	func Parse(input string) (ViewType, error) {
145		if view, ok := resolveView(normalize(input)); ok {
146			return view, nil
147		}
148		return "", nil
149	}
