151	// GetAliases returns every alias with the full name it abbreviates, views and
152	// action commands combined.
153	func GetAliases() map[string]string {
154		aliases := make(map[string]string, len(viewNames)+len(actionAliases))
155		for name, view := range viewNames {
156			if name != string(view) {
157				aliases[name] = string(view)
158			}
159		}
160		maps.Copy(aliases, actionAliases)
161		return aliases
162	}
